items.solution:
function mergeNonBreaking(base, additions) {
  const result = { ...base };
  for (const key of Object.keys(additions)) {
    if (key in base && base[key] !== additions[key]) {
      throw new Error('would overwrite ' + key);
    }
    result[key] = additions[key];
  }
  return result;
}
